class InMemoryRepo {
  #items = new Map();
  #nextId = 1;

  add(name) {
    const id = this.#nextId++;
    this.#items.set(id, { id, name });
    return id;
  }

  get(id) {
    const item = this.#items.get(id);
    return item ? { ...item } : null; // a copy, not the stored object
  }
}
